#include <iostream>
#include <vector>
using namespace std;

const long long MOD = 1000000007;

int n;
vector<int> b;
vector<vector<int>> adj;
vector<long long> C, D;

void dfs(int u, int parent) {
    vector<int> children;
    for (int v : adj[u]) {
        if (v == parent) continue;
        dfs(v, u);
        children.push_back(v);
    }
    int m = children.size();
    long long prod = 1;
    // 计算 C[u] = ∏(C[v] + 1)
    for (int v : children) {
        prod = (prod * (C[v] + 1)) % MOD;
    }
    C[u] = prod;

    // 前缀积与后缀积
    vector<long long> prefix(m + 1, 1), suffix(m + 1, 1);
    for (int i = 0; i < m; i++) {
        int v = children[i];
        prefix[i + 1] = (prefix[i] * (C[v] + 1)) % MOD;
    }
    for (int i = m - 1; i >= 0; i--) {
        int v = children[i];
        suffix[i] = (suffix[i + 1] * (C[v] + 1)) % MOD;
    }

    // 自身贡献
    long long f = (b[u] % 2 == 1) ? 1 : 0;
    long long total = (f * prod) % MOD;
    // 子节点贡献
    for (int i = 0; i < m; i++) {
        int v = children[i];
        long long rest = (prefix[i] * suffix[i + 1]) % MOD;
        total = (total + D[v] * rest) % MOD;
    }
    D[u] = total;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;
    b.resize(n + 1);
    adj.resize(n + 1);
    C.resize(n + 1, 0);
    D.resize(n + 1, 0);

    for (int i = 1; i <= n; i++) {
        cin >> b[i];
    }
    for (int i = 1; i < n; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    dfs(1, 0);

    long long ans = 0;
    for (int i = 1; i <= n; i++) {
        ans = (ans + D[i]) % MOD;
    }
    cout << ans << "\n";

    return 0;
}
